import{_ as a,C as n,c as r,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"POS settings","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/get-started/pos-settings.md","filePath":"master/sales/point-of-sale/get-started/pos-settings.md","lastUpdated":1793074831000}'),l={name:"master/sales/point-of-sale/get-started/pos-settings.md"};function c(g,e,u,d,p,h){const s=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="pos-settings" tabindex="-1">POS settings <a class="header-anchor" href="#pos-settings" aria-label="Permalink to &quot;POS settings&quot;">​</a></h1><p>POS settings are rules shared by every register. They cover default accounts, price lists and when stock is updated. A register can override some of them on its own form. Set these once, before your first session.</p><blockquote><p><strong>In simple words:</strong> Settings are the defaults for all registers. A register can change some of them for itself.</p></blockquote><p>Go to <code>Point of Sale → Settings</code>. Three pages are listed: <strong>Manage Accounts</strong>, <strong>Manage Products</strong> and <strong>Manage Inventory</strong>. Each page has its own <strong>Save changes</strong> button.</p>',4)),o(s,{src:"/images1/pos/settings_menu.png",alt:"Point of Sale Settings sidebar listing Manage Accounts, Manage Inventory and Manage Products"}),e[1]||(e[1]=t('<h2 id="manage-accounts" tabindex="-1">Manage Accounts <a class="header-anchor" href="#manage-accounts" aria-label="Permalink to &quot;Manage Accounts&quot;">​</a></h2><p>Open <code>Point of Sale → Settings → Manage Accounts</code>. These accounts are used when a register has no account of its own.</p><ul><li><strong><em>Default Receivable Account:</em></strong> Holds the money from POS sales until the session closes. A register can use its own <strong>Intermediary Account</strong> instead.</li><li><strong><em>Stock Output Account:</em></strong> The account that receives the cost of items you sell. Used when <strong>Post Cost of Goods Sold</strong> is on.</li><li><strong><em>Default Balancing Account:</em></strong> Takes the small gap when counted cash differs from expected cash at closing.</li><li><strong><em>Post Cost of Goods Sold:</em></strong> Posts a cost entry for sold items from the product cost.</li><li><strong><em>Allow Balancing Line:</em></strong> Lets a closing entry include a balancing line for a cash difference.</li></ul>',3)),o(s,{src:"/images1/pos/settings_manage_accounts.png",alt:"Manage Accounts page with Default Receivable Account, Stock Output Account and Default Balancing Account selected and the toggles shown"}),e[2]||(e[2]=t('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Choose accounts that belong to your company. A register can still pick its own accounts on the <strong>Accounting</strong> tab. See <a href="./set-up-a-register.html">Set up a register</a>.</p></div><h2 id="manage-products" tabindex="-1">Manage Products <a class="header-anchor" href="#manage-products" aria-label="Permalink to &quot;Manage Products&quot;">​</a></h2><p>Open <code>Point of Sale → Settings → Manage Products</code>.</p><ul><li><strong><em>Price Lists:</em></strong> Allows products to be sold at prices set by a price list. Turn it on if you want different prices for groups of customers, or time limited offers.</li></ul><p>After you turn it on, open a register and use the <strong>Pricing</strong> tab to choose <strong>Flexible Pricelists</strong>, <strong>Available Pricelists</strong> and a <strong>Default Pricelist</strong>.</p>',5)),o(s,{src:"/images1/pos/settings_manage_products.png",alt:"Manage Products page with the Price Lists toggle turned on"}),e[3]||(e[3]=t('<h2 id="manage-inventory" tabindex="-1">Manage Inventory <a class="header-anchor" href="#manage-inventory" aria-label="Permalink to &quot;Manage Inventory&quot;">​</a></h2><p>Open <code>Point of Sale → Settings → Manage Inventory</code>.</p><ul><li><strong><em>Inventory Management:</em></strong> Choose when stock quantities drop. <ul><li><strong>In real time:</strong> Stock moves each time an order is paid. Use it when you must see accurate stock all day.</li><li><strong>At the session closing:</strong> Stock moves once, when you close the session. Use it for busy tills where speed matters.</li></ul></li></ul>',3)),o(s,{src:"/images1/pos/settings_manage_inventory.png",alt:"Manage Inventory page with In real time and At the session closing options and one selected"}),e[4]||(e[4]=t('<p>The choice is copied to each new session. Changing it later affects only sessions you open afterwards.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Orders whose stock move needs attention show up as <strong>Failed Operations</strong> on the <a href="./../reporting/dashboard.html">Dashboard</a>.</p></div><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>TechNest Electronics sells the Glide Wireless Mouse all day. The manager picks <strong>In real time</strong> so the stock count stays right. The manager also turns on <strong>Price Lists</strong> so staff can give a loyalty price list to regular customers such as Sofia Rossi.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./set-up-a-register.html">Set up a register</a></li><li><a href="./../sessions/close-session.html">Close a session</a></li><li><a href="./../../../finance/taxes/fiscal-positions.html">Fiscal positions</a></li></ul>',6))])}const _=a(l,[["render",c]]);export{f as __pageData,_ as default};
